package com.spotmeet.backend.controller;

import com.spotmeet.backend.dto.AttendanceListDTO;
import com.spotmeet.backend.service.AttendanceListService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

/** Attendance list: generated by the president, read by active members and organization leaders. */
@RestController
@CrossOrigin(origins = "*")
public class AttendanceListController {

    @Autowired
    private AttendanceListService attendanceListService;

    private String getEmail(Authentication auth) {
        if (auth == null || auth.getName() == null) {
            throw new SecurityException("Usuário não autenticado.");
        }
        return auth.getName();
    }

    /** POST /api/meetings/{meetingId}/attendance-list: generates the list (president only). */
    @PostMapping("/api/meetings/{meetingId}/attendance-list")
    public ResponseEntity<AttendanceListDTO> generate(
            @PathVariable Long meetingId,
            Authentication auth) {
        return ResponseEntity.ok(attendanceListService.generate(meetingId, getEmail(auth)));
    }

    /** GET /api/meetings/{meetingId}/attendance-list: reads the generated list. */
    @GetMapping("/api/meetings/{meetingId}/attendance-list")
    public ResponseEntity<AttendanceListDTO> get(
            @PathVariable Long meetingId,
            Authentication auth) {
        return ResponseEntity.ok(attendanceListService.get(meetingId, getEmail(auth)));
    }
}
